add_action( 'template_redirect', 'perfectpixel_markdown_endpoint', 0 );
add_action( 'wp_head', 'perfectpixel_markdown_alternate_link' );

function perfectpixel_markdown_alternate_link() {
	if ( is_singular() && get_option( 'permalink_structure' ) && ! post_password_required() && 'publish' === get_post_status() ) {
		echo '<link rel="alternate" type="text/markdown" href="' . esc_url( untrailingslashit( get_permalink() ) . '.md' ) . '">' . "\n";
	}
}

function perfectpixel_markdown_endpoint() {
	if ( ! get_option( 'permalink_structure' ) || ! isset( $_SERVER['REQUEST_URI'] ) ) {
		return;
	}
	$path = (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH );
	if ( '.md' !== substr( $path, -3 ) ) {
		return;
	}
	$post_id = url_to_postid( home_url( substr( $path, 0, -3 ) ) );
	$post    = $post_id ? get_post( $post_id ) : null;
	if ( ! $post || 'publish' !== $post->post_status || '' !== $post->post_password || ! is_post_type_viewable( $post->post_type ) ) {
		return;
	}

	$GLOBALS['post'] = $post;
	setup_postdata( $post );
	$html = apply_filters( 'the_content', $post->post_content );
	wp_reset_postdata();

	$doc = new DOMDocument();
	libxml_use_internal_errors( true );
	$doc->loadHTML( '<?xml encoding="utf-8" ?><div>' . $html . '</div>' );
	libxml_clear_errors();
	$body = $doc->getElementsByTagName( 'div' )->item( 0 );
	$md   = '# ' . html_entity_decode( get_the_title( $post ), ENT_QUOTES, 'UTF-8' ) . "\n\n";
	$md  .= 'Source: ' . get_permalink( $post ) . "\n\n";
	$md  .= trim( preg_replace( "/\n{3,}/", "\n\n", perfectpixel_markdown_children( $body ) ) ) . "\n";

	status_header( 200 );
	header( 'Content-Type: text/markdown; charset=utf-8' );
	header( 'X-Robots-Tag: noindex' );
	echo $md; // Plain text response.
	exit;
}

function perfectpixel_markdown_children( $node ) {
	$out = '';
	foreach ( $node->childNodes as $child ) {
		$out .= perfectpixel_markdown_node( $child );
	}
	return $out;
}

function perfectpixel_markdown_node( $node ) {
	if ( XML_TEXT_NODE === $node->nodeType ) {
		return preg_replace( '/\s+/u', ' ', $node->nodeValue );
	}
	if ( XML_ELEMENT_NODE !== $node->nodeType ) {
		return '';
	}
	$tag   = strtolower( $node->nodeName );
	$inner = perfectpixel_markdown_children( $node );
	switch ( $tag ) {
		case 'h1':
		case 'h2':
		case 'h3':
		case 'h4':
		case 'h5':
		case 'h6':
			return "\n\n" . str_repeat( '#', (int) $tag[1] ) . ' ' . trim( $inner ) . "\n\n";
		case 'p':
		case 'div':
		case 'section':
		case 'figure':
			return "\n\n" . trim( $inner ) . "\n\n";
		case 'br':
			return "  \n";
		case 'hr':
			return "\n\n---\n\n";
		case 'strong':
		case 'b':
			return '' === trim( $inner ) ? $inner : '**' . trim( $inner ) . '**';
		case 'em':
		case 'i':
			return '' === trim( $inner ) ? $inner : '*' . trim( $inner ) . '*';
		case 'code':
			return 'pre' === strtolower( $node->parentNode->nodeName ) ? $node->textContent : '`' . $node->textContent . '`';
		case 'pre':
			return "\n\n```\n" . rtrim( $node->textContent ) . "\n```\n\n";
		case 'a':
			$href = $node->getAttribute( 'href' );
			return $href ? '[' . trim( $inner ) . '](' . $href . ')' : $inner;
		case 'img':
			return '![' . $node->getAttribute( 'alt' ) . '](' . $node->getAttribute( 'src' ) . ')';
		case 'blockquote':
			return "\n\n" . preg_replace( '/^/m', '> ', trim( $inner ) ) . "\n\n";
		case 'li':
			$parent = strtolower( $node->parentNode->nodeName );
			$index  = 1;
			for ( $sibling = $node->previousSibling; $sibling; $sibling = $sibling->previousSibling ) {
				$index += ( XML_ELEMENT_NODE === $sibling->nodeType ) ? 1 : 0;
			}
			return ( 'ol' === $parent ? $index . '. ' : '- ' ) . trim( preg_replace( "/\n+/", "\n  ", trim( $inner ) ) ) . "\n";
		case 'ul':
		case 'ol':
			return "\n\n" . $inner . "\n";
		case 'tr':
			$cells = array();
			foreach ( $node->childNodes as $cell ) {
				if ( XML_ELEMENT_NODE === $cell->nodeType ) {
					$cells[] = trim( str_replace( '|', '\|', perfectpixel_markdown_children( $cell ) ) );
				}
			}
			return '| ' . implode( ' | ', $cells ) . " |\n";
		case 'table':
			$rows = array_values( array_filter( explode( "
", trim( $inner ) ) ) );
			if ( $rows ) {
				$cols = max( 1, substr_count( $rows[0], ' | ' ) + 1 );
				array_splice( $rows, 1, 0, '|' . str_repeat( ' --- |', $cols ) );
			}
			return "

" . implode( "
", $rows ) . "

";
		case 'script':
		case 'style':
		case 'noscript':
		case 'form':
		case 'iframe':
			return '';
		default:
			return $inner;
	}
}
